-- =============================================================================
-- Object:      dbo.usp_Order_GetByClientOrderId
-- Type:        stored procedure
-- Purpose:     Returns an order by the id its device generated, so a repeated request gets the order that already
--              exists instead of a duplicate. The items come as JSON in the same row (one result set).
-- Parameters:  @ClientOrderId uniqueidentifier - id generated by the device that took the order
-- Returns:     0 or 1 row: Id, ClientOrderId, OrderNumber, Channel, Status, WaiterId, TableNumber, Total, CreatedAt,
--              ItemsJson (array of ProductId, Name, Quantity, UnitPrice, Subtotal, in the order they were added)
-- Author:      JulianH2
-- Jira:        ITACR-9
-- =============================================================================
CREATE OR ALTER PROCEDURE dbo.usp_Order_GetByClientOrderId
    @ClientOrderId uniqueidentifier
AS
BEGIN
    SET NOCOUNT ON;

    SELECT o.Id, o.ClientOrderId, o.OrderNumber, o.Channel, o.Status, o.WaiterId, t.Number AS TableNumber, o.Total, o.CreatedAt,
        (
            SELECT i.ProductId, p.Name, i.Quantity, i.UnitPrice, i.Subtotal
            FROM dbo.OrderItems AS i
            JOIN dbo.Products AS p ON p.Id = i.ProductId
            WHERE i.OrderId = o.Id
            ORDER BY i.Id
            FOR JSON PATH
        ) AS ItemsJson
    FROM dbo.Orders AS o
    LEFT JOIN dbo.DiningTables AS t ON t.Id = o.TableId
    WHERE o.ClientOrderId = @ClientOrderId;
END;
